/* AutoSeguro — mock de design. Folha compartilhada por todas as telas.
   Paleta derivada da identidade da Namastex: roxo profundo, magenta e ciano. */
:root{
  --fundo:#16012F; --superficie:#1F0A40; --superficie-2:#2A1152; --borda:#3B2068;
  --texto:#F2ECFF; --texto-fraco:#B9A8D9; --texto-mais-fraco:#8B79B0;
  --magenta:#FF00FF; --ciano:#00FFFF; --azul:#198BF5;
  --ok:#3DDC97; --alerta:#FFC857; --falha:#FF5C7A;
  --r:14px; --mono:ui-monospace,"Cascadia Mono",Consolas,monospace;
  --lateral:248px;
}
*{box-sizing:border-box}
body{margin:0;background:var(--fundo);color:var(--texto);
     font:15px/1.5 system-ui,"Segoe UI",Roboto,sans-serif;
     background-image:radial-gradient(900px 500px at 15% -10%, rgba(255,0,255,.10), transparent 60%),
                      radial-gradient(800px 500px at 92% 0%, rgba(0,255,255,.07), transparent 55%);
     background-attachment:fixed}
a{color:var(--ciano)}
h1,h2,h3{letter-spacing:-.2px}

/* ───────── casca: menu lateral + conteúdo ───────── */
.app{display:grid;grid-template-columns:var(--lateral) 1fr;min-height:100vh}
@media (max-width:860px){ .app{grid-template-columns:1fr} .lateral{position:static;height:auto} }

.lateral{position:sticky;top:0;height:100vh;background:rgba(22,1,47,.72);
         border-right:1px solid var(--borda);padding:18px 14px;display:flex;flex-direction:column;gap:18px;
         backdrop-filter:blur(6px)}
.lateral .produto{display:flex;flex-direction:column;gap:3px;padding:4px 8px 0}
.lateral .produto b{font-size:19px;position:relative;display:inline-block}
.lateral .produto b::before,.lateral .produto b::after{content:attr(data-t);position:absolute;inset:0;z-index:-1}
.lateral .produto b::before{color:var(--magenta);transform:translate(-2px,1px)}
.lateral .produto b::after{color:var(--ciano);transform:translate(2px,-1px)}
.lateral .produto span{color:var(--texto-mais-fraco);font-size:11.5px}

.menu{display:flex;flex-direction:column;gap:3px}
.menu .grupo{color:var(--texto-mais-fraco);font-size:10.5px;text-transform:uppercase;
             letter-spacing:.12em;padding:12px 10px 5px}
.menu a{display:flex;align-items:center;gap:10px;padding:9px 11px;border-radius:10px;
        color:var(--texto-fraco);text-decoration:none;font-size:14px;border:1px solid transparent}
.menu a:hover{background:var(--superficie);color:var(--texto)}
.menu a[aria-current="page"]{background:var(--superficie-2);color:var(--texto);
        border-color:var(--borda);box-shadow:inset 2px 0 0 var(--magenta)}
.menu a .ic{width:18px;text-align:center;opacity:.9}
.menu a .cont{margin-left:auto;font-family:var(--mono);font-size:11px;color:var(--texto-mais-fraco)}

.selo{margin-top:auto;display:flex;align-items:center;gap:9px;background:rgba(255,255,255,.04);
      border:1px solid var(--borda);border-radius:12px;padding:9px 10px}
.selo img{height:18px;width:auto;display:block;flex:none}
.selo small{color:var(--texto-mais-fraco);font-size:10.5px;line-height:1.3}

.conteudo{padding:24px 26px 60px;min-width:0}
.cabecalho{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;flex-wrap:wrap;margin-bottom:20px}
.cabecalho h1{margin:0 0 3px;font-size:23px}
.cabecalho p{margin:0;color:var(--texto-fraco);font-size:13.5px;max-width:70ch}

/* ───────── blocos ───────── */
.painel{background:var(--superficie);border:1px solid var(--borda);border-radius:var(--r);overflow:hidden}
.painel > header{padding:12px 16px;border-bottom:1px solid var(--borda);
                 display:flex;align-items:center;justify-content:space-between;gap:12px}
.painel > header h2{margin:0;font-size:12.5px;text-transform:uppercase;letter-spacing:.1em;color:var(--texto-fraco)}
.painel > header .aux{color:var(--texto-mais-fraco);font-size:11.5px;font-family:var(--mono)}

.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(168px,1fr));gap:12px;margin-bottom:20px}
.kpi{background:var(--superficie);border:1px solid var(--borda);border-radius:var(--r);padding:13px 15px}
.kpi .rotulo{color:var(--texto-mais-fraco);font-size:11px;text-transform:uppercase;letter-spacing:.08em}
.kpi .valor{font-size:23px;font-weight:650;margin-top:4px;font-variant-numeric:tabular-nums}
.kpi .nota{color:var(--texto-fraco);font-size:11.5px;margin-top:2px}
.kpi.destaque{border-color:var(--ok)} .kpi.destaque .valor{color:var(--ok)}
.kpi.perigo .valor{color:var(--alerta)}

.chip{display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:2px 9px;
      font-size:11px;font-weight:600;border:1px solid transparent;white-space:nowrap}
