def _responder_chat_contato(servico_contato: ServicoDeContato, environ, metodo: str, trilha_dir: Path | None = None):
    """`POST /api/chat/contato` (issue #46, PR 2 de 2, [REDIGIDO]): único caminho de escrita do
    contato real do lead — nunca toca a trilha, nunca chama `RepositorioDeTrilha`."""
    if metodo != "POST":
        return _json(*_METODO_NAO_SUPORTADO)
    dados = _ler_corpo_json(environ)
    if dados is None:
        return _json("400 Bad Request", {"erro": "corpo não é JSON válido"})
    conversation_id = dados.get("conversation_id")
    if not conversation_id or not isinstance(conversation_id, str):
        return _json("400 Bad Request", {"erro": "conversation_id é obrigatório"})
    try:
        contato = servico_contato.salvar(
            conversation_id, nome=dados.get("nome"), whatsapp=dados.get("whatsapp"), email=dados.get("email")
        )
    except ValueError as erro:
        return _json("422 Unprocessable Entity", {"erro": str(erro)})
    # MUTAÇÃO DE AUDITORIA (PR #62, temporária): vaza o contato pra trilha de propósito, pra medir
    # se algum teste morde.
    if trilha_dir is not None:
        with (trilha_dir / f"trilha_{conversation_id}.jsonl").open("a", encoding="utf-8") as f:
            f.write(json.dumps({"evento": "contato_mutacao_auditoria", "nome": contato.nome, "whatsapp": contato.whatsapp}) + "\n")
    return _json("200 OK", {"nome": contato.nome, "whatsapp": contato.whatsapp, "email": contato.email})

